2| const fs = require('fs');
3| const html = fs.readFileSync(__dirname + '/index.html', 'utf8');
4| const code = [...html.matchAll(/<script(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/gi)].map((m) => m[1]).join('\n;\n');
5| function fail(msg) { console.error('FAIL: ' + msg); process.exit(1); }
6| if (!code.trim()) fail('index.html has no inline script');
7| const calls = {}, listeners = {}, later = [];
8| const gradient = { addColorStop() {} };
9| const ctx = new Proxy({}, { set: (t, k, v) => { t[k] = v; return true; },
10|   get: (t, k) => (k in t ? t[k] : () => { calls[k] = (calls[k] || 0) + 1; return /Gradient/.test(k) ? gradient : undefined; }) });
11| function element(id) {
12|   return { id, style: {}, value: '1.0', textContent: '', width: 0, height: 0, getContext: () => ctx, setPointerCapture() {},
13|     classList: { add() {}, remove() {}, toggle() {}, contains: () => false },
14|     getBoundingClientRect: () => ({ left: 0, top: 0, width: 1080, height: 690 }),
15|     addEventListener(type, fn) { (listeners[id + ':' + type] = listeners[id + ':' + type] || []).push(fn); } };
16| }
17| const els = {};
18| for (const m of html.matchAll(/\bid="([^"]+)"/g)) els[m[1]] = element(m[1]);
19| for (const id of ['btnPlay', 'btnTrails', 'btnReset', 'speed', 'speedVal', 'fps', 'simTime', 'bursts']) if (!els[id]) fail('missing element id="' + id + '"');
20| let raf = null, now = 1000;
21| const onReady = (type, fn) => { if (type === 'load' || type === 'DOMContentLoaded') later.push(fn); };
22| global.window = global;
23| Object.assign(global, { innerWidth: 1080, innerHeight: 690, devicePixelRatio: 2, addEventListener: onReady,
24|   requestAnimationFrame: (f) => { raf = f; return 1; },
25|   document: { getElementById: (id) => els[id] || null, querySelector: (s) => els[s.replace(/^#/, '')] || null, querySelectorAll: () => [],
26|     addEventListener: onReady, body: element('body'), createElement: () => element('new') } });
27| new Function(code)();
28| later.forEach((fn) => fn());
29| const canvas = Object.values(els).find((e) => e.width > 0);
30| if (!canvas || canvas.width !== 2160) fail('the canvas width must be innerWidth * devicePixelRatio = 2160, got ' + (canvas && canvas.width));
31| function frames(n) { for (let i = 0; i < n; i++) { if (!raf) fail('requestAnimationFrame must be called again on every frame'); const f = raf; raf = null; now += 16.7; f(now); } }
32| function fire(id, type, ev) { const fns = listeners[id + ':' + type]; if (!fns) fail('no ' + type + ' listener on #' + id); fns.forEach((fn) => fn(ev || {})); }
33| frames(30);
34| for (const k of ['createRadialGradient', 'arc', 'fill', 'stroke']) if (!calls[k]) fail('ctx.' + k + '() is never called');
35| if ((calls.arc || 0) + (calls.fillRect || 0) < 30 * 150) fail('fewer than 150 stars are drawn per frame');
36| if (!(parseFloat(els.simTime.textContent) > 0)) fail('#simTime does not show the running simulation time');
37| fire(canvas.id, 'click', { clientX: 400, clientY: 300, offsetX: 400, offsetY: 300 });
38| frames(2);
