40| frames(400);
41| if (parseInt(els.bursts.textContent, 10) !== 0) fail('burst particles must fade out and be removed, #bursts still shows ' + els.bursts.textContent);
42| els.speed.value = '2.0'; fire('speed', 'input', { target: els.speed });
43| if (els.speedVal.textContent.trim() !== '2.0x') fail('#speedVal must read "2.0x" after the slider moves to 2.0, got "' + els.speedVal.textContent + '"');
44| fire('btnPlay', 'click'); frames(2);
45| const frozen = els.simTime.textContent; frames(20);
46| if (els.simTime.textContent !== frozen) fail('simulation time must stop while paused');
47| fire('btnPlay', 'click'); fire('btnReset', 'click'); frames(2);
48| if (!(parseFloat(els.simTime.textContent) < 0.5)) fail('Reset must bring the simulation time back to 0, got ' + els.simTime.textContent);
49| fire('btnTrails', 'click'); frames(5);
